INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'نظام حماية البيانات الشخصية — المرسوم الملكي M/19', 'النظام الشامل لحماية البيانات الشخصية في المملكة. يُطبّق على معالجة بيانات الأفراد بما فيها بيانات الاستهلاك المنزلي. سريان كامل من 14 سبتمبر 2024 بعد انتهاء فترة السماح.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/Registration/private/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'نظام حماية البيانات الشخصية (PDPL) — نظرة عامة', 'ينظم معالجة البيانات الشخصية بما فيها بيانات الاستهلاك المنزلي المرتبطة بفرد محدد. يتطلب موافقة صريحة وتحديد غرض المعالجة.', 'https://sdaia.gov.sa/ar/SDAIA/about/Pages/AboutPDPL.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — تحديد الغرض والموافقة', 'يجب جمع البيانات لأغراض محددة وصريحة؛ الاستخدام الثانوي (مثل الإعلانات المستهدفة من بيانات الاستهلاك) يتطلب أساساً قانونياً منفصلاً وموافقة.', 'https://sdaia.gov.sa/ar/SDAIA/about/Pages/AboutPDPL.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — إخفاء الهوية للتحليل', 'قبل تصدير بيانات الأسرة لمسار ML يجب إزالة المعرفات أو استخدام معرفات مجهولة (pseudonymization).', 'https://sdaia.gov.sa/ar/SDAIA/about/Pages/AboutPDPL.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — منع إعلانات من بيانات الاستهلاك', 'استخدام أنماط استهلاك الكهرباء للإعلانات المستهدفة دون موافقة منفصلة يتجاوز غرض إدارة الميزانية — يُرفض في سيناريو SC-03.', 'https://sdaia.gov.sa/ar/SDAIA/about/Pages/AboutPDPL.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — نقل البيانات خارج المملكة', 'يخضع نقل البيانات الشخصية خارج المملكة لضوابط PDPL؛ يجب توثيق الأساس القانوني عند استخدام Supabase/سحابة خارج KSA.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/Registration/private/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'مبادئ وأخلاقيات الذكاء الاصطناعي', 'سبعة مبادئ: عدالة، خصوصية وأمن، إنسانية، منفعة اجتماعية وبيئية، موثوقية وأمان، شفافية وقابلية تفسير، مساءلة ومسؤولية. التوقعات المالية تقديرية وليست ضماناً.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/services/AIEthicsAssessment/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'إطار تبني الذكاء الاصطناعي', 'إطار وطني لتبني AI في القطاعين العام والخاص؛ يلزم بالتوافق مع مبادئ أخلاقيات AI وPDPL.', 'https://sdaia.gov.sa/en/SDAIA/about/Files/AIAdoptionFramework.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'SDAIA — الإشراف البشري', 'يحق للمستخدم التحكم في التنبيهات الآلية؛ Wafir يوفّر إيقاف التنبيهات مؤقتاً (HITL ساعتين).', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/services/AIEthicsAssessment/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'إطار الخدمات المصرفية المفتوحة', 'ينظم مشاركة بيانات الحسابات المصرفية بموافقة المستهلك (AIS/PIS). بيانات عداد الكهرباء خارج النطاق إلا عند تكامل بنكي مستقبلي.', 'https://openbanking.sama.gov.sa/index-en.html') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'SAMA Issues the Open Banking Framework', 'إصدار الإطار الشامل للخدمات المصرفية المفتوحة ضمن استراتيجية FinTech ورؤية 2030؛ يشمل AIS ثم PIS.', 'https://www.sama.gov.sa/en-us/mediacenter/news/pages/news-794.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'حماية المستهلك — SAMA', 'يجب الإفصاح الواضح للمستهلك؛ يُطبّق مبدأ الإفصاح على تنبيهات توقع الفاتورة في Wafir.', 'https://www.sama.gov.sa/en-US/RulesInstructions/Pages/ConsumerProtection.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'إطار الأمن السيبراني — SAMA', 'مرجع لأمن البيانات عند تكامل Wafir مع خدمات مالية مستقبلية.', 'https://www.sama.gov.sa/en-US/RulesInstructions/CyberSecurity/Cyber%20Security%20Framework/Pages/default.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('CMA', 'مختبر التقنية المالية — CMA', 'بيئة تنظيمية تجريبية لمنتجات FinTech في أسواق المال؛ حدود Wafir: تطبيق ميزانية منزلية وليس تداولاً.', 'https://fintech.cma.org.sa/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SERA (ECRA)', 'تعرفة الكهرباء السكنية — هيئة تنظيم الكهرباء', 'التعرفة السكنية: 18 هللة/ك.و.س حتى 6000 ك.و.س/شهر؛ 30 هللة/ك.و.س فما فوق. رسوم العداد 10 ر.س؛ ضريبة 15%.', 'https://www.sera.gov.sa/en/systems-and-regulations/electric-tariff') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SEC', 'الشركة السعودية للكهرباء', 'مزوّد الكهرباء الوطني؛ خدمات العداد والفوترة.', 'https://www.se.com.sa/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('KAUST / SEC', 'KAUST وSEC — تعلم آلي لخسائر الشبكة', 'يُشجّع استخدام ML في قطاع الكهرباء السعودي؛ سياق شرعي لتوقعات الاستهلاك.', 'https://www.kaust.edu.sa/news/kaust-helps-slash-sec-profit-losses-using-ml') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('KAPSARC', 'KAPSARC — كفاءة الطاقة والذكاء الاصطناعي', 'سياق كفاءة الطاقة وتطبيقات الذكاء الاصطناعي في قطاع الطاقة.', 'https://www.kapsarc.org/media/ip0dt4i1/dp00503-v1.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('KAPSARC', 'KBEAT — تحليل كفاءة المباني', 'نصائح توفير الطاقة: 24-26°C للمكيف، عزل حراري، LED.', 'https://apps.kapsarc.org/appboard/kbeat/en') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('MDPI Energies', 'ML for energy consumption forecasting in KSA', 'مرجع أكاديمي لتوقعات استهلاك الطاقة في السعودية.', 'https://www.mdpi.com/1996-1073/16/4/2035') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('ITU-T', 'ITU-T Y.3172', 'إطار خط أنابيب ML: SRC, Collector, PP, Model/MLFO, Sandbox, Policy, Distributor, SINK.', 'https://www.itu.int/rec/T-REC-Y.3172-201906-I') ON CONFLICT DO NOTHING;
